  /// Adds a transformation op, if neeeded, to orient the dome to align with
  /// the stage's up axis (domeLight.cpp:202-218).
  orientToStageUpAxis(): void {
    if (getStageUpAxis(this.prim.getStage()) === 'Z') {
      // UsdGeomXformOp::TypeRotateX with UsdGeomXformOp::PrecisionFloat.
      const opSuffix = UsdLuxTokens.orientToStageUpAxis
      // UsdGeomXformOp::GetOpName(TypeRotateX, opSuffix).
      const opName = `xformOp:rotateX:${opSuffix}`
      // GetOrderedXformOps (xformable.cpp) reads the ops named by
      // xformOpOrder; an op's name is its attribute name, without the
      // "!invert!" prefix, and "!resetXformStack!" names no op.
      const opOrder = this.prim.getAttr('xformOpOrder')?.getValue()
      for (const token of Array.isArray(opOrder) || ArrayBuffer.isView(opOrder)
        ? Array.from(opOrder as ArrayLike<string>) : []) {
        if (token === '!resetXformStack!') continue
        const name = token.startsWith('!invert!') ? token.slice('!invert!'.length) : token
        if (name === opName) {
          // Op already exists.
          return
        }
      }
      this.addRotateXOp(XformOp.PrecisionFloat, opSuffix).set(Math.fround(90.0))
    }
  }
